198	// Configured reports whether a structured checkpoint_remote is configured.
199	func Configured(ctx context.Context) bool {
200		s, err := settings.Load(ctx)
201		if err != nil {
202			logging.Warn(ctx, "checkpoint remote configuration unavailable; treating as not configured",
203				slog.String("error", err.Error()),
204			)
205			return false
206		}
207		return s.GetCheckpointRemote() != nil
208	}
