228	func DeriveCheckpointURL(pushRemoteURL string, config *settings.CheckpointRemoteConfig) (string, error) {
229		info, err := gitremote.ParseURL(pushRemoteURL)
230		if err != nil {
231			return "", fmt.Errorf("cannot parse push remote URL: %w", err)
232		}
233		return deriveCheckpointURLFromInfo(info, config)
234	}
