241	func deriveCheckpointURLFromInfo(info *Info, config *settings.CheckpointRemoteConfig) (string, error) {
242		switch info.Protocol {
243		case ProtocolSSH:
244			return fmt.Sprintf("git@%s:%s.git", info.Host, config.Repo), nil
245		case ProtocolHTTPS:
246			return fmt.Sprintf("https://%s/%s.git", info.Host, config.Repo), nil
247		default:
248			return "", fmt.Errorf("unsupported protocol %q in origin remote", info.Protocol)
249		}
250	}
251	
252	func deriveTokenOriginURL(originURL string) (string, bool) {
253		info, err := gitremote.ParseURL(originURL)
254		if err != nil {
255			return "", false
256		}
257		if info.Host == "" || info.Owner == "" || info.Repo == "" {
258			return "", false
259		}
260		return fmt.Sprintf("https://%s/%s/%s.git", info.Host, info.Owner, info.Repo), true
261	}
