263	func providerHost(provider string) (string, bool) {
264		switch strings.ToLower(strings.TrimSpace(provider)) {
265		case "github":
266			return "github.com", true
267		case "gitlab":
268			return "gitlab.com", true
269		default:
270			return "", false
271		}
272	}
