279	func logFallback(ctx context.Context, operation, fallbackURL, reason string, err error, attrs ...any) {
280		logAttrs := []any{
281			slog.String("operation", operation),
282			slog.String("fallback_url", RedactURL(fallbackURL)),
283			slog.String("reason", reason),
284			slog.String("error", err.Error()),
285		}
286		logAttrs = append(logAttrs, attrs...)
287		logging.Warn(ctx, "checkpoint remote URL resolution fell back to alternate remote URL", logAttrs...)
288	}
