290	func resolvePushFallbackURL(ctx context.Context, pushRemoteName, originURL string) (string, error) {
291		if originURL != "" {
292			return originURL, nil
293		}
294		if pushRemoteName == "" || pushRemoteName == originRemote {
295			return "", fmt.Errorf("remote %q not found", originRemote)
296		}
297		return GetRemoteURL(ctx, pushRemoteName)
298	}
