415	func fetchMetadataFromOrigin(ctx context.Context, shallow bool) error {
416		branchName := paths.MetadataBranchName
417	
418		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
419		defer cancel()
420	
421		fetchTarget, err := strategy.ResolveFetchTarget(ctx, "origin")
422		if err != nil {
423			return fmt.Errorf("failed to resolve fetch target: %w", err)
424		}
425	
426		refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/origin/%s", branchName, branchName)
427		args := []string{"fetch", "--no-tags"}
428		if shallow {
429			args = append(args, "--depth=1")
430		}
431		args = append(args, fetchTarget, refSpec)
432	
433		fetchArgs := strategy.AppendFetchFilterArgs(ctx, args)
434		fetchCmd := strategy.CheckpointGitCommand(ctx, fetchTarget, fetchArgs...)
435		if output, fetchErr := fetchCmd.CombinedOutput(); fetchErr != nil {
436			if ctx.Err() == context.DeadlineExceeded {
437				return errors.New("fetch timed out after 2 minutes")
438			}
439			return formatFilteredFetchError("failed to fetch "+branchName, fetchTarget, output, fetchErr)
440		}
441	
442		repo, err := openRepository(ctx)
443		if err != nil {
444			return fmt.Errorf("failed to open repository: %w", err)
445		}
446	
447		remoteRef, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", branchName), true)
448		if err != nil {
449			return fmt.Errorf("branch '%s' not found on origin: %w", branchName, err)
450		}
451		if err := strategy.SafelyAdvanceLocalRef(ctx, repo, plumbing.NewBranchReferenceName(branchName), remoteRef.Hash()); err != nil {
452			return fmt.Errorf("failed to advance local %s branch: %w", branchName, err)
453		}
454		return nil
455	}
