457	// FetchV2MainTreeOnly fetches the tip of the v2 /main ref from origin with
458	// --depth=1 --filter=blob:none, downloading only the latest commit and its
459	// tree objects (no blobs, no history).
460	// Uses explicit refspec since v2 refs are under refs/entire/, not refs/heads/.
461	func FetchV2MainTreeOnly(ctx context.Context) error {
462		return fetchV2MainFromOrigin(ctx, true /* shallow */)
463	}
