465	// FetchV2MainRef fetches the v2 /main ref from origin.
466	// The fetch is treeless (--filter=blob:none) because /main is metadata-only and
467	// v2 checkpoint reads handle transcript retrieval separately.
468	// Uses explicit refspec since v2 refs are under refs/entire/, not refs/heads/.
469	func FetchV2MainRef(ctx context.Context) error {
470		return fetchV2MainFromOrigin(ctx, false /* shallow */)
471	}
