473	// fetchV2MainFromOrigin fetches the v2 /main ref from origin into the shared
474	// staging ref, then promotes it via strategy.PromoteTmpRefSafely. When
475	// shallow is true, --depth=1 is added so only the tip is downloaded.
476	func fetchV2MainFromOrigin(ctx context.Context, shallow bool) error {
477		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
478		defer cancel()
479	
480		fetchTarget, err := strategy.ResolveFetchTarget(ctx, "origin")
481		if err != nil {
482			return fmt.Errorf("failed to resolve fetch target: %w", err)
483		}
484	
485		refSpec := fmt.Sprintf("+%s:%s", paths.V2MainRefName, strategy.V2MainFetchTmpRef)
486		args := []string{"fetch", "--no-tags"}
487		if shallow {
488			args = append(args, "--depth=1")
489		}
490		args = append(args, fetchTarget, refSpec)
491	
492		fetchArgs := strategy.AppendFetchFilterArgs(ctx, args)
493		fetchCmd := strategy.CheckpointGitCommand(ctx, fetchTarget, fetchArgs...)
494		if output, fetchErr := fetchCmd.CombinedOutput(); fetchErr != nil {
495			if ctx.Err() == context.DeadlineExceeded {
496				return errors.New("v2 fetch timed out after 2 minutes")
497			}
498			return formatFilteredFetchError("failed to fetch v2 /main", fetchTarget, output, fetchErr)
499		}
500	
501		if err := strategy.PromoteTmpRefSafely(ctx, strategy.V2MainFetchTmpRef, paths.V2MainRefName, "v2 /main"); err != nil {
502			return fmt.Errorf("origin v2 /main fetch: %w", err)
503		}
504		return nil
505	}
