507	// FetchV2MetadataFromCheckpointRemote fetches the v2 /main ref from the
508	// configured checkpoint_remote URL.
509	// Returns an error if the fetch fails or no checkpoint_remote is configured.
510	func FetchV2MetadataFromCheckpointRemote(ctx context.Context) error {
511		configured := remote.Configured(ctx)
512		if !configured {
513			return errors.New("no checkpoint_remote configured")
514		}
515		checkpointURL, err := remote.FetchURL(ctx)
516		if err != nil {
517			return fmt.Errorf("checkpoint_remote configured but could not resolve URL: %w", err)
518		}
519	
520		if err := strategy.FetchV2MainFromURL(ctx, checkpointURL); err != nil {
521			return fmt.Errorf("failed to fetch v2 /main from checkpoint remote: %w", err)
522		}
523		return nil
524	}
