545	// resolveCheckpointFetchTarget returns the fetch target for checkpoint data.
546	// It prefers the effective URL resolved by checkpoint/remote.FetchURL, which is
547	// the source of truth for checkpoint fetch location. If URL resolution fails, it
548	// falls back to the origin remote name so callers can still attempt a fetch.
549	func resolveCheckpointFetchTarget(ctx context.Context) string {
550		url, err := remote.FetchURL(ctx)
551		if err == nil && url != "" {
552			return url
553		}
554		return "origin"
555	}
