557	// FetchBlobsByHash fetches specific blob objects from the remote by their SHA-1 hashes.
558	// Uses "git fetch <target> <hash>" which goes through normal credential helpers,
559	// unlike fetch-pack which bypasses them. Requires the server to support
560	// uploadpack.allowReachableSHA1InWant (GitHub, GitLab, Bitbucket all do).
561	//
562	// The fetch target is resolved via resolveCheckpointFetchTarget, which defers to
563	// checkpoint/remote.FetchURL for the effective remote URL when available.
564	//
565	// If fetching by hash fails, falls back to a full metadata branch fetch.
566	func FetchBlobsByHash(ctx context.Context, hashes []plumbing.Hash) error {
567		if len(hashes) == 0 {
568			return nil
569		}
570	
571		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
572		defer cancel()
573	
574		fetchTarget := resolveCheckpointFetchTarget(ctx)
575	
576		args := []string{"fetch", "--no-tags", "--no-write-fetch-head", fetchTarget}
577		for _, h := range hashes {
578			args = append(args, h.String())
