19	// Loader loads a storage.Storer from a URL.
20	type Loader interface {
21		Load(u *url.URL) (storage.Storer, error)
22	}
23	
24	// DefaultLoader is a filesystem loader that resolves paths against the
25	// root filesystem.
26	var DefaultLoader Loader = NewFilesystemLoader(osfs.New(""), false)
27	
28	// FilesystemLoader loads repositories from a billy.Filesystem.
29	type FilesystemLoader struct {
30		base   billy.Filesystem
31		strict bool
32	}
33	
34	// NewFilesystemLoader creates a Loader that resolves URL paths against the
35	// given base filesystem.
36	func NewFilesystemLoader(base billy.Filesystem, strict bool) *FilesystemLoader {
37		return &FilesystemLoader{base: base, strict: strict}
38	}
39	
40	// Load resolves the URL path to a repository on the filesystem.
41	func (l *FilesystemLoader) Load(u *url.URL) (storage.Storer, error) {
42		return l.load(u.Path, false)
43	}
44	
45	func (l *FilesystemLoader) load(path string, tried bool) (storage.Storer, error) {
46		fs, err := l.base.Chroot(path)
47		if err != nil {
48			return nil, err
49		}
50	
51		// Check for .git first (directory or gitfile) to match git's behavior
52		// Git prefers .git/ over a bare repository in the same directory
53		if !tried && !l.strict {
54			if fi, err := fs.Lstat(".git"); err == nil {
55				tried = true
56				if fi.IsDir() {
57					// .git is a directory, use it
58					path = filepath.Join(path, ".git")
59				} else {
60					// .git is a file (gitfile), read the gitdir path
61					gitdir, err := readGitfile(fs)
62					if err != nil {
63						return nil, err
64					}
65					// gitdir can be absolute or relative
66					if filepath.IsAbs(gitdir) {
67						path = gitdir
68					} else {
69						path = filepath.Join(path, gitdir)
70					}
71				}
72				return l.load(path, tried)
73			}
74		}
75	
76		// Check for config file to detect bare repository
77		fi, err := fs.Lstat("config")
78		if err != nil || fi.IsDir() {
79			if !l.strict && !tried {
80				// No .git and no config, try appending .git
81				tried = true
82				path += ".git"
83				return l.load(path, tried)
84			}
85			return nil, ErrRepositoryNotFound
86		}
87	
88		return filesystem.NewStorageWithOptions(fs, cache.NewObjectLRUDefault(), filesystem.Options{}), nil
89	}
90	
91	// readGitfile reads a .git file and extracts the gitdir path.
92	// The .git file should contain a single line: "gitdir: <path>"
93	func readGitfile(fs billy.Filesystem) (string, error) {
94		f, err := fs.Open(".git")
95		if err != nil {
96			return "", err
97		}
98		defer func() { _ = f.Close() }()
99	
100		reader := bufio.NewReader(f)
101		line, err := reader.ReadString('\n')
102		if err != nil && err != io.EOF {
103			return "", err
104		}
105	
106		const prefix = "gitdir: "
107		if !strings.HasPrefix(line, prefix) {
108			return "", fmt.Errorf(".git file has no %s prefix", prefix)
109		}
110	
111		gitdir := strings.TrimSpace(line[len(prefix):])
112		return gitdir, nil
113	}
114	
115	// MapLoader is a Loader that uses a lookup map keyed by URL path.
116	type MapLoader map[string]storage.Storer
117	
118	// Load returns a storer for the given URL path.
119	func (l MapLoader) Load(u *url.URL) (storage.Storer, error) {
120		s, ok := l[u.Path]
121		if !ok {
122			return nil, ErrRepositoryNotFound
123		}
124		return s, nil
125	}
