1	// Package gitremote provides general-purpose git remote URL utilities:
2	// parsing, resolving, and redacting remote URLs. It has no dependency on
3	// checkpoint, strategy, or settings packages.
4	package gitremote
5	
6	import (
7		"context"
8		"fmt"
9		"net/url"
10		"os/exec"
11		"strings"
12	)
13	
14	const (
15		ProtocolSSH   = "ssh"
16		ProtocolHTTPS = "https"
17	)
18	
19	// Info holds the parsed components of a git remote URL.
20	type Info struct {
21		Protocol string
22		Host     string
23		Owner    string
24		Repo     string
25	}
26	
27	// GetRemoteURL returns the URL configured for the named git remote.
28	func GetRemoteURL(ctx context.Context, remoteName string) (string, error) {
29		cmd := exec.CommandContext(ctx, "git", "remote", "get-url", remoteName)
30		output, err := cmd.Output()
31		if err != nil {
32			return "", fmt.Errorf("remote %q not found", remoteName)
33		}
34		return strings.TrimSpace(string(output)), nil
35	}
36	
37	// ParseURL parses a git remote URL (SSH SCP-style or HTTPS) into its components.
38	func ParseURL(rawURL string) (*Info, error) {
39		rawURL = strings.TrimSpace(rawURL)
40	
41		if strings.Contains(rawURL, ":") && !strings.Contains(rawURL, "://") {
42			parts := strings.SplitN(rawURL, ":", 2)
43			if len(parts) != 2 {
44				return nil, fmt.Errorf("invalid SSH URL: %s", RedactURL(rawURL))
45			}
46	
47			hostPart := parts[0]
48			_, host, found := strings.Cut(hostPart, "@")
49			if !found {
50				host = hostPart
51			}
52	
53			pathPart := strings.TrimSuffix(parts[1], ".git")
54			owner, repo, err := splitOwnerRepo(pathPart)
55			if err != nil {
56				return nil, err
57			}
58	
59			return &Info{Protocol: ProtocolSSH, Host: host, Owner: owner, Repo: repo}, nil
60		}
61	
62		u, err := url.Parse(rawURL)
63		if err != nil {
64			return nil, fmt.Errorf("invalid URL: %s", RedactURL(rawURL))
65		}
66		if u.Scheme == "" {
67			return nil, fmt.Errorf("no protocol in URL: %s", RedactURL(rawURL))
68		}
69	
70		pathPart := strings.TrimPrefix(u.Path, "/")
71		owner, repo, err := splitOwnerRepo(pathPart)
72		if err != nil {
73			return nil, err
74		}
75	
76		return &Info{Protocol: u.Scheme, Host: u.Hostname(), Owner: owner, Repo: repo}, nil
77	}
78	
79	// RedactURL removes credentials and query parameters from a URL for safe logging.
80	// SCP-style SSH URLs (e.g., git@github.com:org/repo.git) are returned as-is
81	// since they contain no embedded credentials.
82	func RedactURL(rawURL string) string {
83		// SCP-style SSH: user@host:path — no credentials to redact.
84		if strings.Contains(rawURL, ":") && !strings.Contains(rawURL, "://") {
85			return rawURL
86		}
87	
88		u, err := url.Parse(rawURL)
89		if err != nil {
90			return "<unparseable>"
91		}
92		u.User = nil
93		u.RawQuery = ""
94		return u.Scheme + "://" + u.Host + u.Path
95	}
96	
97	// ExtractOwnerFromRemoteURL extracts the owner component from a git remote URL.
98	// Returns an empty string if the URL cannot be parsed.
99	func ExtractOwnerFromRemoteURL(rawURL string) string {
100		info, err := ParseURL(rawURL)
101		if err != nil {
102			return ""
103		}
104		return info.Owner
105	}
106	
107	// ResolveRemoteRepo returns the host, owner, and repo name for the given git remote.
108	// It parses the remote URL (SSH or HTTPS) and extracts the components.
109	// For example, git@github.com:org/my-repo.git returns ("github.com", "org", "my-repo").
110	func ResolveRemoteRepo(ctx context.Context, remoteName string) (host, owner, repo string, err error) {
111		rawURL, err := GetRemoteURL(ctx, remoteName)
112		if err != nil {
113			return "", "", "", fmt.Errorf("get remote URL for %q: %w", remoteName, err)
114		}
115		info, err := ParseURL(rawURL)
116		if err != nil {
117			return "", "", "", fmt.Errorf("parse remote URL: %w", err)
118		}
119		return info.Host, info.Owner, info.Repo, nil
120	}
121	
122	func splitOwnerRepo(path string) (string, string, error) {
123		path = strings.TrimSuffix(path, ".git")
124		parts := strings.SplitN(path, "/", 2)
125		if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
126			return "", "", fmt.Errorf("cannot parse owner/repo from path: %s", path)
127		}
128		return parts[0], parts[1], nil
129	}
