180	func extractRemoteFromArgs(args []string) string {
181		if len(args) < 2 {
182			return ""
183		}
184		// Skip subcommand (e.g., "push", "fetch", "ls-remote").
185		for _, arg := range args[1:] {
186			if !strings.HasPrefix(arg, "-") {
187				return arg
188			}
189		}
190		return ""
191	}
