193	// appendCheckpointTokenEnv appends GIT_CONFIG_COUNT-based env vars to inject
194	// an Authorization header into git HTTP requests. The token is sent as a Basic
195	// credential with the format "x-access-token:<token>" (base64-encoded), which
196	// is compatible with GitHub's token authentication.
197	// It filters out any pre-existing GIT_CONFIG_COUNT/KEY/VALUE entries to avoid
198	// conflicts, then appends the new ones.
199	//
200	// NOTE: This drops ALL existing GIT_CONFIG_* entries from the environment.
201	// If a parent process (e.g., CI) injects its own GIT_CONFIG_* vars, they will
202	// be lost. If that becomes an issue, read the existing count and append at the
203	// next index instead of replacing.
204	func appendCheckpointTokenEnv(baseEnv []string, token string) []string {
205		filtered := make([]string, 0, len(baseEnv)+3)
206		for _, e := range baseEnv {
207			if strings.HasPrefix(e, "GIT_CONFIG_COUNT=") ||
208				strings.HasPrefix(e, "GIT_CONFIG_KEY_") ||
209				strings.HasPrefix(e, "GIT_CONFIG_VALUE_") {
210				continue
211			}
212			filtered = append(filtered, e)
213		}
214		encoded := base64.StdEncoding.EncodeToString([]byte("x-access-token:" + token))
215		return append(filtered,
216			"GIT_CONFIG_COUNT=1",
217			"GIT_CONFIG_KEY_0=http.extraHeader",
218			"GIT_CONFIG_VALUE_0=Authorization: Basic "+encoded,
219		)
220	}
221	
222	// isValidToken returns false if the token contains control characters (bytes < 0x20
223	// or 0x7F). This prevents HTTP header injection via CR/LF or other control chars
224	// embedded in the token value.
225	func isValidToken(token string) bool {
226		for _, b := range []byte(token) {
227			if b < 0x20 || b == 0x7F {
228				return false
229			}
230		}
231		return true
232	}
