234	// resolveTargetProtocol determines whether a push/fetch target uses SSH or HTTPS.
235	// Returns ProtocolSSH, ProtocolHTTPS, or "" if unknown.
236	func resolveTargetProtocol(ctx context.Context, target string) string {
237		var rawURL string
238		if IsURL(target) {
239			rawURL = target
240		} else {
241			// Remote name — resolve to URL
242			var err error
243			rawURL, err = GetRemoteURL(ctx, target)
244			if err != nil {
245				return ""
246			}
247		}
248	
249		info, err := ParseURL(rawURL)
250		if err != nil {
251			return ""
252		}
253		return info.Protocol
254	}
