256	// ensureEnv appends an environment variable to the command, initializing
257	// cmd.Env from os.Environ() if it is nil.
258	func ensureEnv(cmd *exec.Cmd, envVar string) {
259		if cmd.Env == nil {
260			cmd.Env = os.Environ()
261		}
262		cmd.Env = append(cmd.Env, envVar)
263	}
